export const LEGAL_KEYS: LegalDocKey[] = ['terms', 'privacy', 'consent'];

/**
 * Редакции по документам — в таком виде они ложатся в запись о согласии.
 *
 * Здесь именно `version`, а не та, по которой решают спрашивать заново: в
 * записи должно остаться, какой текст человек видел, а не к какому поколению
 * согласий он относится.
 */
export function legalVersions(): Record<'terms' | 'privacy' | 'consent', string> {
  return {
    terms: LEGAL_DOCS.terms.version,
    privacy: LEGAL_DOCS.privacy.version,
    consent: LEGAL_DOCS.consent.version,
  };
}

/** Версии общего согласия вместе с отдельно подтверждённой трансграничной редакцией. */
export function legalVersionsWithCrossBorder(): Record<string, string> {
  return {
    ...legalVersions(),
    crossBorderConsent: LEGAL_DOCS.crossBorderConsent.version,
  };
}

/** Принята ли именно текущая редакция отдельного трансграничного согласия. */
export function hasCrossBorderConsent(docs: Record<string, string> | null | undefined): boolean {
  return docs?.crossBorderConsent === LEGAL_DOCS.crossBorderConsent.version;
}

/**
 * Отпечаток набора — одна строка вида
 * `terms:2026-06-25|privacy:2026-06-25|consent:2026-06-25`.
 *
 * Галочка одна на все три документа, поэтому и сравнивать удобнее набор
 * целиком: изменилось хоть что-то — отпечаток другой, и это сигнал спросить.
 *
 * Собирается из `consentVersion`, а не из `version`. Иначе правка контакта
 * поднимала бы окно согласия у всех — см. пояснение у самого поля.
 */
export const LEGAL_STAMP: string = LEGAL_KEYS
  .map(k => `${k}:${LEGAL_DOCS[k].consentVersion}`)
  .join('|');

/**
 * Нужно ли спрашивать согласие заново.
 *
 * Пустая запись значит «не спрашивали вовсе» — так у всех, кто
 * регистрировался до 25 июня 2026, когда экрана с документами ещё не было.
 */
export function needsReconsent(recorded: string | null | undefined): boolean {
  return !recorded || recorded !== LEGAL_STAMP;
}

/** «25 июня 2026» — для показа в интерфейсе. */
export function formatLegalDate(version: string): string {
  const MONTHS = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня',
                  'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'];
  const [y, m, d] = version.split('-').map(Number);
  if (!y || !m || !d) return version;
  return `${d} ${MONTHS[m - 1]} ${y}`;
}
